public with sharing class ErpCustomerSync {
    private static final Integer CALLS_PER_JOB = 50;

    public class SyncJob implements Queueable {
        private final List<Id> accountIds;

        public SyncJob(List<Id> accountIds) {
            this.accountIds = accountIds;
        }

        public void execute(QueueableContext context) {
            if (accountIds == null || accountIds.isEmpty()) {
                return;
            }

            Integer currentBatchSize = accountIds.size() < CALLS_PER_JOB ? accountIds.size() : CALLS_PER_JOB;
            List<Id> currentIds = new List<Id>();
            for (Integer i = 0; i < currentBatchSize; i++) {
                currentIds.add(accountIds[i]);
            }

            List<Account> accounts = [
                SELECT Id, Name, BillingCountry
                FROM Account
                WHERE Id IN :currentIds
            ];

            for (Account account : accounts) {
                sendCustomer(account);
            }

            if (accountIds.size() > currentBatchSize) {
                List<Id> remainingIds = new List<Id>();
                for (Integer i = currentBatchSize; i < accountIds.size(); i++) {
                    remainingIds.add(accountIds[i]);
                }
                System.enqueueJob(new SyncJob(remainingIds));
            }
        }
    }

    public static void enqueueForNewAccounts(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<Id> accountIds = new List<Id>();
        for (Account account : accounts) {
            accountIds.add(account.Id);
        }

        System.enqueueJob(new SyncJob(accountIds));
    }

    private static void sendCustomer(Account account) {
        JSONGenerator generator = JSON.createGenerator();
        generator.writeStartArray();
        generator.writeStartObject();

        generator.writeStringField('salesforceId', account.Id.toString());
        generator.writeStringField('name', account.Name == null ? '' : account.Name);

        if (isBlank(account.BillingCountry)) {
            generator.writeNullField('country');
        } else {
            generator.writeStringField('country', account.BillingCountry);
        }

        generator.writeEndObject();
        generator.writeEndArray();

        HttpRequest request = new HttpRequest();
        request.setEndpoint('callout:ERP/api/customers');
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setBody(generator.getAsString());
        request.setTimeout(120000);

        new Http().send(request);
    }

    private static Boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
}
