public with sharing class AccountCountrySync {
    private static final Integer SOQL_IN_CHUNK_SIZE = 1000;
    private static final Integer DML_CHUNK_SIZE = 15000;

    public static void syncContacts(List<Account> oldAccounts, List<Account> newAccounts) {
        if (oldAccounts == null || newAccounts == null || oldAccounts.size() != newAccounts.size()) {
            return;
        }

        Map<Id, String> oldCountryByAccount = new Map<Id, String>();
        Map<Id, String> newCountryByAccount = new Map<Id, String>();
        List<Id> changedAccountIds = new List<Id>();

        for (Integer i = 0; i < newAccounts.size(); i++) {
            Account oldAccount = oldAccounts.get(i);
            Account newAccount = newAccounts.get(i);

            if (newAccount == null || oldAccount == null || newAccount.Id == null) {
                continue;
            }

            if (!isSameCountry(newAccount.BillingCountry, oldAccount.BillingCountry)) {
                changedAccountIds.add(newAccount.Id);
                oldCountryByAccount.put(newAccount.Id, oldAccount.BillingCountry);
                newCountryByAccount.put(newAccount.Id, newAccount.BillingCountry);
            }
        }

        if (changedAccountIds.size() == 0) {
            return;
        }

        Map<Id, Contact> contactsToUpdate = new Map<Id, Contact>();

        if (changedAccountIds.size() <= SOQL_IN_CHUNK_SIZE) {
            processContacts(
                [SELECT Id, AccountId, MailingCountry FROM Contact WHERE AccountId IN :changedAccountIds],
                oldCountryByAccount,
                newCountryByAccount,
                contactsToUpdate
            );
        } else {
            for (Integer i = 0; i < changedAccountIds.size(); i += SOQL_IN_CHUNK_SIZE) {
                Integer chunkEnd = Math.min(i + SOQL_IN_CHUNK_SIZE, changedAccountIds.size());
                List<Id> accountChunk = new List<Id>();
                for (Integer j = i; j < chunkEnd; j++) {
                    accountChunk.add(changedAccountIds[j]);
                }

                processContacts(
                    [SELECT Id, AccountId, MailingCountry FROM Contact WHERE AccountId IN :accountChunk],
                    oldCountryByAccount,
                    newCountryByAccount,
                    contactsToUpdate
                );
            }
        }

        if (contactsToUpdate.size() > 0) {
            List<Contact> updates = new List<Contact>();
            for (Contact c : contactsToUpdate.values()) {
                updates.add(c);
            }

            if (updates.size() <= DML_CHUNK_SIZE) {
                update updates;
            } else {
                for (Integer i = 0; i < updates.size(); i += DML_CHUNK_SIZE) {
                    Integer chunkEnd = Math.min(i + DML_CHUNK_SIZE, updates.size());
                    List<Contact> contactChunk = new List<Contact>();
                    for (Integer j = i; j < chunkEnd; j++) {
                        contactChunk.add(updates[j]);
                    }
                    update contactChunk;
                }
            }
        }
    }

    private static void processContacts(
        List<Contact> contacts,
        Map<Id, String> oldCountryByAccount,
        Map<Id, String> newCountryByAccount,
        Map<Id, Contact> contactsToUpdate
    ) {
        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }

            if (!oldCountryByAccount.containsKey(c.AccountId) ||
                !newCountryByAccount.containsKey(c.AccountId)) {
                continue;
            }

            String oldCountry = oldCountryByAccount.get(c.AccountId);
            String newCountry = newCountryByAccount.get(c.AccountId);

            if (isBlank(c.MailingCountry) || isSameCountry(c.MailingCountry, oldCountry)) {
                if (!isSameCountry(c.MailingCountry, newCountry)) {
                    c.MailingCountry = newCountry;
                    contactsToUpdate.put(c.Id, c);
                }
            }
        }
    }

    private static Boolean isBlank(String value) {
        return value == null || value.trim().length() == 0;
    }

    private static Boolean isSameCountry(String a, String b) {
        if (isBlank(a) && isBlank(b)) {
            return true;
        }

        if (isBlank(a) || isBlank(b)) {
            return false;
        }

        return a.trim().equals(b.trim());
    }
}
